Q: How to debounce / throttle with Svelte? A: <pre><code>&lt;script&gt;
    let val = $state('');

    function debounce(cb, t) {
        let timer;
        return (...args) =&gt; {
            clearTimeout(timer);
            timer = setTimeout(() =&gt; cb(...args), t);
        }
    }
&lt;/script&gt;

&lt;input oninput={debounce( (event) =&gt; val = event.target.value, 600 )} /&gt;
{val}
</code></pre>
